package controlsys

import (
	"testing"

	"plantcontrol.org/v1/gonum/mat"
)

// TestDare_ReducedInputsConvergedXGainNotCertifiedWrong: with rank-deficient
// B (n 6, m 7; reduced, not rotated inputs), cheap control (R about 3e-7)
// and an upper-triangular E with last pivot 2.6e-3, X refined to within
// 2e-15 of the 320-bit X had a Newton step of 1.2e-16, so it came without
// the Newton iterate gainMiss also measures K against; K, the ddGain of
// that X, was measured against itself and Dare returned it at Accuracy 0,
// 2.6e-4 off the 320-bit gain (band 1.5e-4), the gain of the next iterate
// 2.2e-4 from it (V4OJPR, rv49vGen 4917, NoScaling true, native). K stays
// within its band at Accuracy 0.
func TestDare_ReducedInputsConvergedXGainNotCertifiedWrong(t *testing.T) {
	A := mat.NewDense(6, 6, []float64{-0.504884223449384, -0.12195317760917654, 0.29117297319125296, 0.17755280349526836, -1.3283033833668967, 0.34144118299364351, 0.18763883578660592, 0.091550607539872528, -0.19087694914527945, 0.064565453998944741, 0.96028164135215033, 0.084923576492826433, 0.1126717536536834, -0.53182235709945846, -0.19669278317330952, -0.72746534564122622, -0.044502589659692289, -0.46013418936260231, -0.49580279025344659, 0.70625419083797281, 0.12264566811603915, -0.25384067134646499, -0.29850273690098456, 0.11491822242006636, 0.2670018901034642, 0.67148595428486035, -0.1779575966950723, -0.21619386991142514, 0.09063213226119686, -0.22921141065583717, 0.76807855015051774, 0.17917406385277496, 0.69270868007800335, 0.38201464893068704, 0.84903253095120257, 0.15151574201090376})
	B := mat.NewDense(6, 7, []float64{-1.1443906145850691, -0.029099967005058347, -1.5843659790965656, 0.61049285835445444, -0.88705424401373878, 0.69663506833180122, -0.56409337685266192, -1.0561275226161868, -0.58575436119207303, -1.5944707637499964, -0.035065492703025836, 0.35319798986209155, -0.60131488260290977, -0.77278544227591306, -1.3997642860917381, 0.54128839967777787, -0.35112492304815446, -0.48284339904490392, 1.0509038911580406, 0.56716852470999901, 1.1157322922216508, 0.52854333074518234, -0.82542717477955707, 1.0249599886176841, 0.63003463724948816, 0.27704842722478684, -0.16902183296148293, -1.3254193035696435, -0.37863447671557071, -0.86592263257853053, -0.2810066324595476, 1.5027946833057442, 1.3459655521210523, 0.60785666480086931, 0.15008632509096564, -0.029228791623433711, 0.28082492753453536, 1.1143161016751351, -1.301034186489169, 0.38651048825424072, 1.3179027479485876, -0.62880860337146793})
	Q := mat.NewDense(6, 6, []float64{266.15759155784104, -376.22572095999766, -41.060040833347692, -429.09687730423673, -782.80626242140295, -165.66712369185856, -376.22572095999766, 531.81197005650495, 58.040213599603732, 606.54772640737087, 1106.5318435130584, 234.17792701506883, -41.060040833347692, 58.040213599603732, 6.3343184891639526, 66.196628848533379, 120.76325500051732, 25.55741064426001, -429.09687730423673, 606.54772640737087, 66.196628848533379, 691.78612954285597, 1262.0332216457839, 267.08704806078259, -782.80626242140295, 1106.5318435130584, 120.76325500051732, 1262.0332216457839, 2302.3414094615314, 487.24990763656274, -165.66712369185856, 234.17792701506883, 25.55741064426001, 267.08704806078259, 487.24990763656274, 103.11783974183248})
	R := mat.NewDense(7, 7, []float64{3.283848955161868e-07, -1.4142481846177003e-09, -5.993286715349877e-10, -9.036264783313e-09, -7.2654021630170543e-09, 1.3025348788143166e-08, -3.6616020748709934e-09, -1.4142481846177003e-09, 3.5568822660357249e-07, 1.9069114345399459e-08, -1.0912449857776125e-08, 1.4133787900807189e-08, 5.4770509563755431e-09, 2.624250147677386e-09, -5.993286715349877e-10, 1.9069114345399459e-08, 3.4737789080254969e-07, -2.8879352955444185e-09, -2.4048366241782973e-09, 1.4699001967959791e-08, -4.6901215615597068e-09, -9.036264783313e-09, -1.0912449857776125e-08, -2.8879352955444185e-09, 3.2394400641236804e-07, 3.4812457794246355e-09, -5.3225702186526062e-09, 2.0460553157256493e-09, -7.2654021630170543e-09, 1.4133787900807189e-08, -2.4048366241782973e-09, 3.4812457794246355e-09, 3.4657548274676928e-07, -8.4921347590368357e-09, 1.5514668484903832e-09, 1.3025348788143166e-08, 5.4770509563755431e-09, 1.4699001967959791e-08, -5.3225702186526062e-09, -8.4921347590368357e-09, 3.4070916436183074e-07, -2.1912849684624188e-09, -3.6616020748709934e-09, 2.624250147677386e-09, -4.6901215615597068e-09, 2.0460553157256493e-09, 1.5514668484903832e-09, -2.1912849684624188e-09, 3.1800062318529396e-07})
	E := mat.NewDense(6, 6, []float64{1.1061493344198441, -0.34389320296891357, 0.32664754896710929, -0.36118197483481207, -0.29841067718880526, 0.3029730065463499, 0, 1.0267555587669932, -0.58588594867868049, 0.030143997190838934, 0.25203693770594615, -0.22757908349934794, 0, 0, 1.1898006426908108, -0.30066068799994505, -0.10440354097429827, 0.069939977660228622, 0, 0, 0, 1.0468007555253254, 0.44849731796208225, -0.17473910325532183, 0, 0, 0, 0, 1.0854153377728852, -0.2509958092545666, 0, 0, 0, 0, 0, 0.002569084033965649})
	ref := riccatiExactReference(false, A, B, Q, R, nil, E, riccatiExactPrec)
	sens, ok := riccatiExactSensitivity(false, A, B, Q, R, nil, E, ref, "ABQRSE")
	if !ref.OK || !ok {
		t.Fatal("reference not certified")
	}
	for _, ns := range []bool{false, true} {
		for _, c := range []struct {
			name  string
			solve func(A, B, Q, R *mat.Dense, opts *RiccatiOpts) (*RiccatiResult, error)
			x     *mat.Dense
			xBand float64
		}{{"Dare", Dare, ref.X, sens.X}, {"Dlqr", Dlqr, ref.Y, sens.Y}} {
			res, err := c.solve(A, B, Q, R, &RiccatiOpts{E: E, NoScaling: ns})
			if err != nil {
				t.Errorf("%s NoScaling %v: %v", c.name, ns, err)
				continue
			}
			eX, eK := relErr(res.X, c.x), relErr(res.K, ref.K)
			t.Logf("%s NoScaling %v: Accuracy %d, X err %.3g (band %.3g), K err %.3g (band %.3g)", c.name, ns, res.Accuracy, eX, c.xBand, eK, sens.KBand())
			if riccatiCertifiedWrong(res.Accuracy, eX, c.xBand, eK, sens.KBand(), gainFloor) {
				t.Errorf("%s NoScaling %v: certified-wrong: X err %g, K err %g", c.name, ns, eX, eK)
			}
		}
	}
}
